const SmartQualityReportPage   = dynamic(() => import('@/components/pages/quality-kpi/smart-report/SmartQualityReportPage'), { loading: () => <PageSkeleton />, ssr: false });

// ─── Background preload ───────────────────────────────────────────────────────
function PreloadPages() {
  React.useEffect(() => {
    const hasIdle = 'requestIdleCallback' in window;
    const id = hasIdle
      ? window.requestIdleCallback(() => {
          import('@/components/pages/EmployeesPage');
          import('@/components/pages/AttendancePage');
        })
      : window.setTimeout(() => {
          import('@/components/pages/EmployeesPage');
          import('@/components/pages/AttendancePage');
        }, 200);
    return () => {
      if (hasIdle) window.cancelIdleCallback(id as number);
      else clearTimeout(id as number);
    };
  }, []);
  return null;
}

// ─── Access denied ────────────────────────────────────────────────────────────
function AccessDenied() {
  const pageConfig = APP_PAGES.find((p) => p.id === useAppStore.getState().currentPage);
  return (
    <div className="flex flex-col items-center justify-center py-24">
      <div className="w-20 h-20 rounded-2xl bg-red-500/10 border border-red-500/20 flex items-center justify-center mb-6">
        <ShieldX className="w-10 h-10 text-red-400" />
      </div>
      <h2 className="text-xl font-bold text-slate-200 mb-2">صلاحية غير كافية</h2>
      <p className="text-slate-400 text-center max-w-md">
        ليس لديك صلاحية للوصول إلى {pageConfig?.title || 'هذه الصفحة'}.
        يرجى التواصل مع مدير النظام إذا كنت تعتقد أن هذا خطأ.
      </p>
    </div>
  );
}

// ─── §SIDEBAR-BADGES: mark-on-open ────────────────────────────────────────────
// Opening a monitored page marks THAT module seen for the CURRENT user
// only (per-user state — other users' badges are unaffected). The call
// is optimistic (badge clears instantly) and fires once per navigation;
// the record data itself is fetched by the page as usual.
function MarkSeenOnOpen({ page }: { page: string }) {
  const markSeen = useMarkSeen();
  React.useEffect(() => {
    markSeen(page);
    // One mark per navigation — the page id is the dependency.
  }, [page]);
  return null;
}

// ─── Page router ──────────────────────────────────────────────────────────────
function PageRouter() {
  const currentPage = useAppStore((s) => s.currentPage);
  const { canViewPage } = usePermissions();

  // §USER-PROFILE — 'profile' is admitted like 'home': every
  // authenticated user owns their profile, and /api/profile is
  // self-scoped server-side (requireAuth), so there is nothing to
  // escalate. Everything else stays permission-gated.
  if (
    currentPage !== 'home' &&
    currentPage !== 'profile' &&
    !canViewPage(currentPage)
  ) {
    return <AccessDenied key="access-denied" />;
  }

  return (
    <>
      <MarkSeenOnOpen page={currentPage} />
      {renderPage(currentPage)}
    </>
  );
}

function renderPage(currentPage: string): React.ReactNode {
  switch (currentPage) {
    case 'home':             return <HomePage             key="home" />;
    case 'employees':        return <EmployeesPage        key="employees" />;
    case 'biometric':        return <BiometricPage        key="biometric" />;
    case 'attendance':       return <AttendancePage       key="attendance" />;
    case 'requests':         return <RequestsPage         key="requests" />;
    case 'rules':            return <RulesPage            key="rules" />;
    case 'quality':          return <QualityPage          key="quality" />;
    case 'hrDeductions':     return <HrDeductionsPage     key="hrDeductions" />;
    case 'travel':           return <TravelPage           key="travel" />;
    case 'reports':          return <ReportsPage          key="reports" />;
    case 'qualityDeductionsReport': return <QualityDeductionsReportPage key="qualityDeductionsReport" />;
    case 'controlPanel':     return <ControlPanelPage     key="controlPanel" />;
    case 'organization':     return <OrganizationPage     key="organization" />;
    case 'settings':         return <SettingsPage         key="settings" />;
    case 'profile':          return <ProfilePage          key="profile" />;
    case 'followUps':        return <FollowUpsPage        key="followUps" />;
    case 'capa':             return <CAPAPage             key="capa" />;
    case 'complaints':       return <ComplaintsPage       key="complaints" />;
    case 'knowledgeBase':    return <KnowledgeBasePage    key="knowledgeBase" />;
    case 'riskCenter':       return <RiskCenterPage       key="riskCenter" />;
    case 'operationsCenter': return <OperationsCenterPage key="operationsCenter" />;
    // §NOTIFICATIONS-V2: no 'notifications' case — the standalone page
    // was removed; store.navigateTo intercepts the id and opens the
    // Header bell panel instead.
    case 'rulesEngine':      return <RulesEnginePage      key="rulesEngine" />;
    case 'workflowDesigner': return <WorkflowDesignerPage key="workflowDesigner" />;
    // ── Quality KPI (Phase 1) ──
    case 'observations':          return <ObservationsPage          key="observations" />;
    case 'observationCategories': return <ObservationCategoriesPage key="observationCategories" />;
    case 'observationTemplates':  return <ObservationTemplatesPage  key="observationTemplates" />;
    case 'kpiDashboard':          return <KpiDashboardPage          key="kpiDashboard" />;
    case 'kpiReports':            return <KpiReportsPage            key="kpiReports" />;
    case 'smartQualityReport':    return <SmartQualityReportPage    key="smartQualityReport" />;
    case 'monthClose':            return <MonthClosePage            key="monthClose" />;
    case 'kpiSettings':           return <KpiSettingsPage           key="kpiSettings" />;
    case 'qualityAuditLog':       return <QualityAuditLogPage       key="qualityAuditLog" />;
    default:                      return <HomePage                  key="home" />;
  }
}

// ─── App content ──────────────────────────────────────────────────────────────
// Rendered inside AppShell's z-10 layer.
// AppShell handles the loading overlay (z-20) independently.
// This component only manages the login ↔ ready transition.
function AppContent() {
  const { user, loading } = useAuth();

  // While loading, render nothing — AppShell's LoadingOverlay covers the screen.
  // Once loading resolves, animate in either login or the app.
  if (loading) return null;

  return (
    <>
      <PreloadPages />

      {/* Login overlay — fades in/out above the persistent background */}
      <AnimatePresence>
        {!user && <LoginPage key="login" />}
      </AnimatePresence>

      {/* App — mounts after login, unmounts on logout */}
      {user && (
        <NotificationProvider>
          <AppLayout>
            <PageRouter />
          </AppLayout>
        </NotificationProvider>
      )}
    </>
  );
}

// ─── Root ─────────────────────────────────────────────────────────────────────
export default function Home() {
  return (
    <LanguageProvider>
      <AuthProvider>
      {/*
       * AppShell mounts once. It owns:
       *   - PersistentBackground (z-0, React.memo, never re-renders)
       *   - LoadingOverlay       (z-20, AnimatePresence, fades out after session check)
       *
       * AppContent (z-10) manages login ↔ ready with its own AnimatePresence.
       * The two AnimatePresence instances are siblings, not nested.
       */}
      <AppShell>
        <AppContent />
      </AppShell>
      </AuthProvider>
    </LanguageProvider>
  );
}
