// src/lib/i18n/en-map.ts
// ══════════════════════════════════════════════════════════════
//  §20.1-EN — the ENGLISH runtime map, keyed by the Arabic SOURCE
//  text as it appears in the rendered UI.
//
//  Why keyed-by-source? The application was authored Arabic-first with
//  inline strings across hundreds of components. Migrating every file
//  to `t()` keys is a long-tail effort; this map lets the runtime
//  translator (§20.1-RUNTIME) deliver a complete professional English
//  surface TODAY, with zero per-file churn:
//    • exact-match: a text node whose trimmed content equals the key
//    • bounded phrase match: the Arabic phrase replaced inside longer
//      text ONLY at whole-word boundaries (never inside a word), so
//      composed labels («القسم: X») translate while user data (names,
//      notes) passes through untouched.
//  The map is additive: unmapped strings simply remain Arabic until
//  they are added here.
// ══════════════════════════════════════════════════════════════

